private string GetSoGocFullName(DataRow drw)
{
    string strFullName = GetHtmlValue(drw, "StudentFullName");
    if (strFullName != "&nbsp;")
        return strFullName;

    string strFirst = "";
    string strLast = "";
    if (drw.Table.Columns.Contains("StudentFirstName") && drw["StudentFirstName"] != DBNull.Value)
        strFirst = drw["StudentFirstName"].ToString();
    if (drw.Table.Columns.Contains("StudentLastName") && drw["StudentLastName"] != DBNull.Value)
        strLast = drw["StudentLastName"].ToString();
    string strName = (strFirst + " " + strLast).Trim();
    if (strName == "")
        return "&nbsp;";
    return strName;
}

