private string GetSoGocCourseListHtml()
{
    Hashtable hst = new Hashtable();
    ArrayList arrList = new ArrayList();
    DataView dv = dtbData.DefaultView;
    dv.Sort = "CourseName, SpecialBranchName";

    foreach (DataRowView drv in dv)
    {
        DataRow drw = drv.Row;
        if (!MatchPrintFilter(drw, true))
            continue;

        string strCourse = drw["CourseName"].ToString();
        string strBranch = drw["SpecialBranchName"].ToString();
        string strKey = strCourse + "|" + strBranch;
        if (hst.ContainsKey(strKey))
            continue;

        hst[strKey] = 1;
        arrList.Add(String.Format("Khóa {0} ( Nghề {1})", strCourse, strBranch));
    }

    StringBuilder sb = new StringBuilder();
    sb.Append("<table class='course-list'><tr>");
    sb.Append("<td class='course-label'>Khóa học:</td>");
    sb.Append("<td class='course-items'>");
    for (int i = 0; i < arrList.Count; i++)
    {
        if (i > 0)
            sb.Append("<br />");
        sb.Append(arrList[i].ToString());
    }
    if (arrList.Count == 0)
        sb.Append("&nbsp;");
    sb.Append("</td></tr></table>");
    return sb.ToString();
}

private string GetSoGocDecisionInfo()
{
    string strDecisionNo = "";
    DateTime? dtmSign = null;

    if (dtbData != null)
    {
        foreach (DataRow drw in dtbData.Rows)
        {
            if (!MatchPrintFilter(drw, true))
                continue;

            if (strDecisionNo == "" && drw["DecisionNo"].ToString() != "")
                strDecisionNo = drw["DecisionNo"].ToString();

            if (dtmSign == null && drw["Signingdate"] != DBNull.Value && drw["Signingdate"].ToString() != "")
            {
                try
                {
                    dtmSign = Convert.ToDateTime(drw["Signingdate"]);
                }
                catch
                {
                }
            }

            if (strDecisionNo != "" && dtmSign != null)
                break;
        }
    }

    string strNo = strDecisionNo != "" ? strDecisionNo : "........";
    string strDate = "..../..../........";
    if (dtmSign != null)
        strDate = dtmSign.Value.ToString("dd/MM/yyyy");

    return String.Format("Quyết định công nhận tốt nghiệp số: {0} ngày {1}", strNo, strDate);
}

