private void ExportSoGocToHTML()
{
    if (!IsValidExamDate())
        return;

    if (dtbData == null || dtbData.Rows.Count <= 0)
    {
        MessageManager.Warning("Không có dữ liệu để in!");
        return;
    }

    int intCount = CountEligibleForPrint();
    if (intCount <= 0)
    {
        MessageManager.Warning("Không có học viên nào đủ điều kiện (TBC > 5) để in sổ gốc!");
        return;
    }

    string strFileContent = Libs.Files.ReadFile(HTML_TEMPLATE_SO_GOC);
    if (strFileContent == null || strFileContent == "")
    {
        MessageManager.Warning("Không tìm thấy file mẫu HTML!");
        return;
    }

    DateTime dtmSign = GetSoGocSignDate();
    string strPlaceDate = String.Format("{0}, ngày {1} tháng {2} năm {3}",
        GetReportPlace(), dtmSign.Day, dtmSign.Month, dtmSign.Year);

    strFileContent = strFileContent.Replace("{HEADER_TEXT}", GetReportHeaderText());
    strFileContent = strFileContent.Replace("{HEADER2_TEXT}", GetReportHeader2Text());
    strFileContent = strFileContent.Replace("{COURSE_LIST}", GetSoGocCourseListHtml());
    strFileContent = strFileContent.Replace("{DECISION_INFO}", GetSoGocDecisionInfo());
    strFileContent = strFileContent.Replace("{DETAIL}", SoGocDetailToHTML());
    strFileContent = strFileContent.Replace("{PLACE_DATE}", strPlaceDate);

    string strFileNameAs = "SoGocCapChungChiDaoTaoThuongXuyen_" + intExamDateID.ToString() + ".htm";
    Libs.Files.WriteFile(strFileNameAs, strFileContent);
    System.Diagnostics.Process.Start(strFileNameAs);
}

